library ieee;
use     ieee.std_logic_1164.all;
use     ieee.numeric_std.all;
use     ieee.math_real.all;

library work;
use     work.qol_pkg.all;
use     work.vic_pkg.all;


entity border is
port
(
	clk    : in  std_wire;
	rst    : in  std_wire;

	strb   : in  t_strb;
	specs  : in  t_vic_specs;
	cycl   : in  t_ppos;
	xpos   : in  t_ppos;

right_context:
	enable : in  std_word(1 downto 0);

	mark_bord : out std_wire;
	mark_colr : out t_colr
);
end entity;


architecture rtl of border is

	signal rst_1r   : std_wire := '1';

	signal ff_main  : std_wire;
	signal ff_vert  : std_wire;

	signal edge_ll  : t_ppos;
	signal edge_rr  : t_ppos;
	signal edge_hi  : t_ppos;
	signal edge_lo  : t_ppos;

	signal reg_rsel : std_wire;
	signal reg_csel : std_wire;

	signal reg_rsel_1r : std_wire;
	signal reg_csel_1r : std_wire;

	alias  reg_ec   : std_word is reg(32)(3 downto 0);
	alias  reg_den  : std_wire is reg(17)(4);

begin

	----------------------------------------------------------------------------
	--                             DIAGNOSTICS                                --
	----------------------------------------------------------------------------

	process(all) is
	begin
		reg_rsel <= reg(17)(3);
		reg_csel <= reg(22)(3);

		if enable = "01" then
			-- force wide border
			reg_rsel <= '1';
			reg_csel <= '1';
		elsif enable = "10" then
			-- force narrow border
			reg_rsel <= '0';
			reg_csel <= '0';
		end if;
	end process;

	----------------------------------------------------------------------------

	edge_ll <= specs.xfvc + 7 when (reg_csel = '0') else specs.xfvc;
	edge_rr <= specs.xlvc - 8 when (reg_csel = '0') else specs.xlvc + 1;
	edge_hi <= specs.yfvc + 4 when (reg_rsel = '0') else specs.yfvc;
	edge_lo <= specs.ylvc - 3 when (reg_rsel = '0') else specs.ylvc + 1;

	P_border : process(clk) is
		variable v_ff_main : std_wire;
		variable v_ff_vert : std_wire;
	begin
		if rising_edge(clk) then

			v_ff_main := ff_main;
			v_ff_vert := ff_vert;

			if strb(0) = '1' then

				-- vertical ff control
				if (ypos = edge_lo) then
					v_ff_vert := '1';
				end if;

				if (xpos = edge_ll) then
					o_vbrd <= v_ff_vert;
				end if;

				if (ypos = edge_hi) and (reg_den = '1') then
					v_ff_vert := '0';
					o_vbrd    <= v_ff_vert;
				end if;

				-- main ff control
				if (xpos = edge_rr) then
					v_ff_main := '1';
				end if;
				if (xpos = edge_ll) and (v_ff_vert = '0') then
					v_ff_main := '0';
				end if;

				-- this is copied from kawarii
				if (cycl = 0)then
					o_vbrd <= v_ff_vert;
				end if;

				o_bord <= v_ff_main;
				o_colr <= t_colr(reg_ec);

				ff_vert <= v_ff_vert;
				ff_main <= v_ff_main;

				----------------------------------------------------------------
				--                       DIAGNOSTICS                          --
				----------------------------------------------------------------

				-- turning off border
				if enable = "00" then
					o_bord <= '0';
				end if;

				-- marking csel and rsel changes (opening border)
				reg_csel_1r <= reg_csel;
				reg_rsel_1r <= reg_rsel;

				mark_bord <= '0';
				if reg_csel_1r /= reg_csel then
					mark_bord <= '1';
					mark_colr <= x"d"; -- LIGHT GREEN
				end if;

				if reg_rsel_1r /= reg_rsel then
					mark_bord <= '1';
					mark_colr <= x"4"; -- PURPLE
				end if;

				----------------------------------------------------------------

			end if;

			rst_1r <= rst;
			if rst_1r then
				ff_main <= '0';
				ff_vert <= '0';
			end if;

		end if;
	end process;

end architecture;

groundtruth:
ypos   : in  t_ppos;
reg    : in  t_regs;

o_vbrd : out std_wire;

right_context:
	i_a      : in  t_addr;
	i_rw     : in  std_wire;
	i_cs     : in  std_wire;
	i_aec    : in  std_wire;

	o_ph0    : out std_wire;
	o_db     : out std_word(11 downto 0);
	o_a      : out t_addr;
	o_rw     : out std_wire;
	o_cs     : out std_wire;
	o_aec    : out std_wire
);
end entity;


architecture rtl of bus_latch is

	signal vector_in  : std_word(21 downto 0);
	signal vector_out : std_word(21 downto 0);

begin

	process(all) is
	begin
		vector_in <= i_ph0 & i_db & std_word(i_a) & i_rw & i_cs & i_aec;
		o_ph0     <= vector_out(21);
		o_db      <= vector_out(20 downto 9);
		o_a       <= unsigned(vector_out(8 downto 3));
		o_rw      <= vector_out(2);
		o_cs      <= vector_out(1);
		o_aec     <= vector_out(0);
	end process;


	i_multi_flop : entity work.multi_flop
	generic map
	(
		g_num_stages => switch(g_enable, 2, 0),
		g_input_reg  => false
	)
	port map
	(
		i_clk  => clk,
		i_rst  => rst,
		i_data => vector_in,

		o_clk  => clk,
		o_rst  => rst,
		o_data => vector_out
	);

end architecture;

