  type rgb4_array_t is array (integer range <>) of rgb4_t;
  type word_array_t is array (integer range <>) of word_t;
  type byte_array_t is array (integer range <>) of byte_t;

  constant RGA_STRHOR   : addr_t := x"03C";

right_context:
