  constant RGA_COLOR07  : addr_t := x"18E";

  type denise_in_t is record
    clk7    : std_ulogic;
    cck     : std_ulogic;
    rga     : std_ulogic_vector( 8 downto  1);
    drd     : std_ulogic_vector(15 downto  0);
