  constant CCK_PERIOD : time := 280 ns;
  signal clk7       : std_ulogic := '0';
  signal cck        : std_ulogic := '0';
  signal deni       : denise_in_t;
  signal deno       : denise_out_t;

  signal drd            : std_logic_vector (15 downto  0);
