  rga_bfm0 : entity ocs.rga_bfm_impl
  port map (
    -- clocks are driven out on deni
    clk7      => clk7,
    cck       => cck,
    deni      => deni,
    deno      => deno
  );

  deno.drd <= drd;
  drd <= deni.drd;

